/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields on 25 Mar 2022 by chaminda
/// Creating multi tread batch tasks
/// </summary>

class METPOConfirmationPostMiltiTreadBatch extends RunBaseBatch
{
    // Packed variables
    BatchHeader batchHeader;
    container   companyAndPurchId;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        companyAndPurchId
    #endmacro
   
}

Method.Source:
    /// <summary>
    /// Contains the code that does the actual job of the class.
    /// </summary>
    public void run()
    {
        #OCCRetryCount
        #Characters
        int i;                  
        METPOConfirmationPostMultiTreadTask metPOConfirmationPostMultiTreadTask;      
        for(i=1;i<=conLen(companyAndPurchId);i++)
        {
            container companyAndPurchIdSingle           = conPeek(companyAndPurchId,i);

            if(!batchHeader)
            {
                batchHeader = BatchHeader::construct(this.parmCurrentBatch().BatchJobId);
            }
            batchHeader.parmCaption("@MET:PurchaseOrderConfirmationMultiTreadBatchJob");
            metPOConfirmationPostMultiTreadTask = new METPOConfirmationPostMultiTreadTask();
            metPOConfirmationPostMultiTreadTask.pramCompanyAndPurchId(companyAndPurchIdSingle);
            // add tasks to the batch header
            batchHeader.addRuntimeTask(metPOConfirmationPostMultiTreadTask, this.parmCurrentBatch().RecId);
            
        } 
        if(batchHeader)
        {
            // save the batchheader with added tasks
            batchHeader.save();
        }
    }

    public boolean unpack(container packedClass)
    {
        Version version = RunBase::getVersion(packedClass);
        ;
        switch (version)
        {
            case #CurrentVersion:
                [version,#CurrentList] = packedClass;
                break;
            default:
                return false;
        }

        return true;
    }

/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields on 25 Mar 2022 by chaminda    
/// </summary>
/// <param name="_companyAndPurchIds"> Get container</param>    
public void pramCompanyAndPurchIds(container _companyAndPurchIds)
{
    companyAndPurchId = _companyAndPurchIds;
}

static METPOConfirmationPostMiltiTreadBatch construct()
{
    return new METPOConfirmationPostMiltiTreadBatch();
}

/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields on 25 Mar 2022 by chaminda
/// <returns>
/// A ClassDescription
/// </returns>
/// Here goes a description of the class
/// </summary>

static ClassDescription description()
{
    return "@MET:PurchaseOrderConfirmationMultiTreadBatchJob";
}

    static void main(Args args)
    {
        METPOConfirmationPostMiltiTreadBatch    metPOConfirmationPostMiltiTreadBatch;
    
        metPOConfirmationPostMiltiTreadBatch = METPOConfirmationPostMiltiTreadBatch::construct();

        if (metPOConfirmationPostMiltiTreadBatch.prompt())
        {
            metPOConfirmationPostMiltiTreadBatch.runOperation();
        }
    }
